import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"复数延时器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/modules/complex_delay/index.md","filePath":"v0.3.0-alpha/modules/complex_delay/index.md"}'),r={name:"v0.3.0-alpha/modules/complex_delay/index.md"};function l(c,t,i,h,n,p){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="复数延时器" tabindex="-1">复数延时器 <a class="header-anchor" href="#复数延时器" aria-label="Permalink to &quot;复数延时器&quot;">​</a></h1><p>适用：v0.3.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>complex_delay</code> · 模块定义版本：6</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>按 item 推迟完整复数样本，用于观察复数信号的时间关系。I 与 Q 一起移动，二者之间的对应关系保持不变。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>复数信号源.out → 复数延时器.in</code>，从 <code>out</code> 读取结果。多路使用成对的 <code>in2 → out2</code> 等路径；消息口 <code>dly</code> 与复数流口分开。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（输入）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输入</td><td><code>dly</code>（dly（消息））</td><td><code>message</code></td><td>消息；不计入流路数</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>延时量按完整 item 计，向量 item 中的全部复数分量同时移动。对应时间为延时 item 数除以 item 采样率；不能再乘向量长度当作时间。</p><p>对于单频相量，时间推迟表现为相位变化，但对包含多频率的信号，固定延时与固定复增益的作用不同。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>延时采样数<br><code>delay_samples</code></td><td><code>0</code></td><td>范围 0 至 2147483647</td><td>可在线应用</td></tr><tr><td>输入／输出对数<br><code>num_ports</code></td><td><code>1</code></td><td>范围 1 至 1024；当前画布支持 1–1024 路。修改后须重新准备，缩减前请先解除相关连线和工具绑定。</td><td>重新准备</td></tr><tr><td>每个 item 的向量长度<br><code>vlen</code></td><td><code>1</code></td><td>范围 1 至 1024；Master 当前容量限制为 1–1024；采样率按 item 计。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>delay_samples</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>运行时调整延时会改变缓冲状态，切换附近的波形应按实际样本解释。端口对数或向量长度变化后重新准备。</p><p>当前属性页未提供 <code>dly</code> 消息投递表单，相关消息步骤由配套开发验证脚本调用运行控制接口执行。打开工程后普通 F5 只运行工程中的初始图，不会恢复上次消息造成的延时变化。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="复数处理与-i-q-往返" tabindex="-1">复数处理与 I/Q 往返 <a class="header-anchor" href="#复数处理与-i-q-往返" aria-label="Permalink to &quot;复数处理与 I/Q 往返&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/complex-iq.cnsproj" download>下载 complex-iq.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>复数处理与 I/Q 往返</p><ul><li>观察复数旋转相量、乘 j 的相位变化及 I/Q 分解再合成；复数频谱保留正负频率。</li></ul><p>复数处理示例使用 8 item 延时。起始填充之后，输出应与输入更早 8 item 的复数值相同；同时核对 I 与 Q，而不是分别寻找近似相似的两段曲线。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>I 看起来对上，Q 却没有？</strong> 检查是否选中了同一输入和输出样本；不要独立平移两个分量。</p><p><strong>能用延时器改变采样率吗？</strong> 不能，延时保持长期 item 速率，速率变换应由适配的滤波模块完成。</p>',29)])])}const u=e(r,[["render",l]]);export{m as __pageData,u as default};
